-- ----------------------------------------------------------
-- MBTI 人格测试模块 (zhice / 智测心理测试系统)
-- 生成时间: 2026-10-21
-- 包含: 4 张表 + 60 道标准题库 + 16 型人格说明 + 菜单
-- 适用: MySQL 8.0
-- ----------------------------------------------------------
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `mbti_answers`;
DROP TABLE IF EXISTS `mbti_records`;
DROP TABLE IF EXISTS `mbti_questions`;
DROP TABLE IF EXISTS `mbti_types`;

CREATE TABLE `mbti_questions` (
  `question_id` bigint NOT NULL AUTO_INCREMENT COMMENT '题目ID',
  `question_no` int NOT NULL COMMENT '题号',
  `dimension` char(2) NOT NULL COMMENT '维度: EI/SN/TF/JP',
  `content` varchar(255) NOT NULL COMMENT '题干引导语',
  `option_a` varchar(500) NOT NULL COMMENT '选项A文字',
  `option_a_pole` char(1) NOT NULL COMMENT '选项A对应极',
  `option_b` varchar(500) NOT NULL COMMENT '选项B文字',
  `option_b_pole` char(1) NOT NULL COMMENT '选项B对应极',
  `status` char(1) DEFAULT '0' COMMENT '状态(0正常 1停用)',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`question_id`),
  UNIQUE KEY `uk_question_no` (`question_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='MBTI题目表';

CREATE TABLE `mbti_records` (
  `record_id` bigint NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `user_name` varchar(64) DEFAULT NULL COMMENT '测试人',
  `result_type` char(4) NOT NULL COMMENT '结果类型(如 INTJ)',
  `score_e` int DEFAULT 0 COMMENT 'E得分',
  `score_i` int DEFAULT 0 COMMENT 'I得分',
  `score_s` int DEFAULT 0 COMMENT 'S得分',
  `score_n` int DEFAULT 0 COMMENT 'N得分',
  `score_t` int DEFAULT 0 COMMENT 'T得分',
  `score_f` int DEFAULT 0 COMMENT 'F得分',
  `score_j` int DEFAULT 0 COMMENT 'J得分',
  `score_p` int DEFAULT 0 COMMENT 'P得分',
  `duration` int DEFAULT 0 COMMENT '用时(秒)',
  `test_time` datetime DEFAULT NULL COMMENT '测试时间',
  PRIMARY KEY (`record_id`),
  KEY `idx_mbti_records_user` (`user_id`),
  KEY `idx_mbti_records_type` (`result_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='MBTI测试记录表';

CREATE TABLE `mbti_answers` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '答案ID',
  `record_id` bigint NOT NULL COMMENT '记录ID',
  `question_id` bigint NOT NULL COMMENT '题目ID',
  `choice` char(1) NOT NULL COMMENT '选择(A/B)',
  PRIMARY KEY (`id`),
  KEY `idx_mbti_answers_record` (`record_id`),
  CONSTRAINT `mbti_answers_ibfk_1` FOREIGN KEY (`record_id`) REFERENCES `mbti_records` (`record_id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='MBTI答题明细表';

CREATE TABLE `mbti_types` (
  `type_code` char(4) NOT NULL COMMENT '类型代码',
  `type_name` varchar(32) NOT NULL COMMENT '中文别称',
  `nick_name` varchar(64) DEFAULT NULL COMMENT '英文别称',
  `group_name` varchar(32) DEFAULT NULL COMMENT '所属群体',
  `color` varchar(16) DEFAULT NULL COMMENT '主题色',
  `summary` varchar(255) DEFAULT NULL COMMENT '一句话概述',
  `description` text COMMENT '性格描述',
  `strengths` text COMMENT '优势',
  `weaknesses` text COMMENT '劣势',
  `careers` text COMMENT '适合职业',
  `relationships` text COMMENT '人际关系',
  `famous` text COMMENT '代表人物',
  PRIMARY KEY (`type_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='MBTI十六型人格表';

