INSERT INTO `mbti_questions` VALUES (50, 50, 'JP', '请选择更符合你的一项', '我的计划常变，习惯随时调整', 'P', '一天结束时，我会把待办清单逐项勾掉', 'J', '0', '2026-10-21 00:00:00');
