INSERT INTO `mbti_questions` VALUES (53, 53, 'JP', '请选择更符合你的一项', '面对规则，我倾向于遵守既定流程', 'J', '面对规则，我觉得应该灵活变通', 'P', '0', '2026-10-21 00:00:00');
INSERT INTO `mbti_questions` VALUES (54, 54, 'JP', '请选择更符合你的一项', '我的日程留白很多，走一步看一步', 'P', '我的日程通常安排得比较满、有条理', 'J', '0', '2026-10-21 00:00:00');
