INSERT INTO `mbti_questions` VALUES (56, 56, 'JP', '请选择更符合你的一项', '别人说我更可能是随性、灵活、好相处的', 'P', '别人说我更可能是有条理、靠谱的', 'J', '0', '2026-10-21 00:00:00');
