INSERT INTO `mbti_questions` VALUES (59, 59, 'JP', '请选择更符合你的一项', '面对不确定的情况，我会感到不安、想尽快确定', 'J', '面对不确定的情况，我觉得有意思、享受未知', 'P', '0', '2026-10-21 00:00:00');
INSERT INTO `mbti_questions` VALUES (60, 60, 'JP', '请选择更符合你的一项', '我更认同边走边看、允许变化', 'P', '我更认同先完成再完善', 'J', '0', '2026-10-21 00:00:00');
INSERT INTO `mbti_types` VALUES ('INTJ', '建筑师', 'Architect', '分析家', '#7E57C2', '富有想象力和战略眼光的思考者，一切都在计划之中。', '你习惯从长远和系统的角度看待问题，善于把复杂信息迅速归纳成清晰的模型与路径。你独立、自律，对认定的目标有不妥协的坚持，不喜欢低效流程和无谓社交。你相信能力和逻辑，也愿意为了长期价值做短期忍耐。', '战略思维和全局观强；独立解决问题能力突出；高度自律、执行到位；善于抽象建模与深度学习', '容易显得冷静甚至冷漠；对他人的情绪需求不够敏感；完美主义，容易否定别人的方案；不擅长表达感受', '战略规划、系统架构、科研、数据科学、投资分析、管理咨询、产品架构', '你重质不重量，需要能进行思想层面交流的关系。表达感情是弱项，但一旦承诺非常忠诚。建议多说一句在意，比默默做好更重要。', '牛顿、马斯克、尼采（一般认为）、福尔摩斯');
INSERT INTO `mbti_types` VALUES ('INTP', '逻辑学家', 'Logician', '分析家', '#7E57C2', '富有创造力的思想家，对知识有着止不住的渴望。', '你热衷于探究事物背后的原理，喜欢把概念拆开再重组。你不太在意世俗的评价，更在意自己的逻辑是否自洽。你享受思考本身带来的乐趣，讨厌被规则和情绪绑架，思考过后常常忘了行动。', '分析和抽象能力极强；能发现别人忽略的矛盾；独立思考、不盲从；对新知识保持长期好奇', '容易陷入过度分析、迟迟不动手；忽视人情与时间节点；表达偏冷，容易被误解为不关心；讨厌重复性事务', '算法与研发、学术研究、数据分析、架构设计、技术写作、逻辑与哲学相关工作', '你需要能容忍你沉默发呆、也能跟你讨论奇怪问题的伙伴。你不擅长主动维护关系，提醒自己偶尔表达温度，会让对方更安心。', '爱因斯坦、达尔文、笛卡尔、图灵');
INSERT INTO `mbti_types` VALUES ('ENTJ', '指挥官', 'Commander', '分析家', '#7E57C2', '大胆、富有想象力的领导者，总能找到或创造出路。', '你天然地想掌控局面，看到问题会立刻构思解决方案并推动落地。你目标感强、决策果断，不怕承担压力，也乐于把团队带向更高的目标。你相信效率和结果，对拖延和含糊最不耐烦。', '领导力和决断力强；善于组织资源、推动执行；逻辑清晰、抗压能力好；敢于挑战现状', '过于强势，容易压人；对情绪和耐心不足；忽略细节和人的感受；承认错误比较困难', '企业高管、创业、项目管理、销售与商务、投资并购、运营统筹', '你在感情中直接、主动、有担当，但容易把关系也当成项目来管。多给对方决策空间、少一点指令，关系会更舒服。', '拿破仑、乔布斯、撒切尔夫人、玛格丽特·撒切尔式企业家');
INSERT INTO `mbti_types` VALUES ('ENTP', '辩论家', 'Debater', '分析家', '#7E57C2', '聪明好奇的思考者，无法抗拒智力的挑战。', '你脑子转得快，喜欢试探各种可能，也喜欢用辩论来打磨观点。你对新点子兴奋，对常规不以为然。你能看到一件事的十个角度，也因此容易在最后一公里失去兴趣。', '创意和应变能力强；善于说服和拆解问题；接受新事物快；不怕冲突、敢于挑战权威', '容易喜新厌旧、缺乏收尾；说话不留情面、偶尔为了辩论而辩论；对流程和细节缺乏耐心', '创业、产品策划、市场与品牌、咨询、法务辩论、媒体内容、创新研发', '你欣赏能跟你斗嘴、又不真的动气的伴侣。你的兴奋点很高，但需要有人帮你把约定落实，不要把承诺也当成脑洞。', '苏格拉底、富兰克林、马克·吐温、爱因斯坦（常被归入此类）');
INSERT INTO `mbti_types` VALUES ('INFJ', '提倡者', 'Advocate', '外交家', '#33A474', '安静而神秘，却能鼓舞人心的理想主义者。', '你对人的情绪和动机异常敏锐，能感受到别人没说出口的东西。你内心有清晰的价值观，愿意为自己相信的意义长期付出。你看起来温和，实际上非常坚持，只是不喜欢冲突。', '洞察人心、共情力强；有长远理想且能落地；文字与表达细腻；善于引导他人成长', '容易过度付出、精疲力竭；对自己和他人都要求高；不愿麻烦别人、闷着消耗；讨厌冲突所以常常委屈自己', '心理咨询、教育、人力资源、公益组织、内容创作、用户研究、医疗健康', '你渴望深度联结，宁缺毋滥。会为在乎的人投入很多，但要练习说出自己的需求，而不是等对方猜。', '马丁·路德·金、柏拉图、特蕾莎修女（一般认为）、荣格');
INSERT INTO `mbti_types` VALUES ('INFP', '调停者', 'Mediator', '外交家', '#33A474', '诗意、善良的利他主义者，总想为正义事业出力。', '你有丰富的内心世界，重视真实和意义，讨厌被贴标签。你对人有天然善意，愿意理解不同立场。你在意的东西往往很抽象：公平、美、真诚，这些比结果更让你在意。', '共情和创造力强；忠于价值观；善于用文字/艺术表达；包容、不轻易评判他人', '容易逃避冲突和现实事务；完美主义导致拖延；情绪内耗多；难以做世俗意义上的取舍', '写作与创作、心理与教育、设计、公益、翻译、内容编辑、艺术相关工作', '你需要的是被理解而不是被改造。你的爱安静但很深，注意别把不满憋成沉默，及时沟通能避免误会。', '莎士比亚、托尔金、村上春树式作家、卢梭');
INSERT INTO `mbti_types` VALUES ('ENFJ', '主人公', 'Protagonist', '外交家', '#33A474', '富有魅力、鼓舞人心的领导者，有感染力地凝聚他人。', '你天然关注他人的成长和感受，擅长把一群人团结在共同目标下。你表达温暖、行动积极，愿意承担组织者的角色。你需要被需要，也在意自己是否真的帮到了别人。', '感染力和领导力强；善于沟通协调；共情与责任心兼具；推动团队氛围和凝聚力', '过度在意别人的评价；容易牺牲自己照顾所有人；对批评敏感；有时过于理想化', '管理、教育培训、市场公关、人力资源、咨询、公益与社区运营', '你投入、体贴、乐于经营关系，但要小心把照顾变成控制。留一点空间给自己，关系才能长久。', '奥普拉、马丁·斯科塞斯式导演、巴拉克·奥巴马（常被归入）');
INSERT INTO `mbti_types` VALUES ('ENFP', '竞选者', 'Campaigner', '外交家', '#33A474', '热情、有创造力的社交者，总能找到让人开心的理由。', '你对世界保持好奇，容易对人产生兴趣，也容易点燃别人。你讨厌重复和束缚，喜欢自由地探索可能。你情感充沛，做事靠热情驱动，兴致来的时候效率惊人。', '热情有感染力；创意多、联想能力强；善于与人建立联系；适应变化快', '容易三分钟热度、缺乏坚持；讨厌细节和收尾；情绪起伏大；计划性弱', '市场与品牌、内容创作、活动策划、销售、教育、创业、公共关系', '你浪漫、投入、喜欢新鲜感，需要自由也需要陪伴。和你在一起的人要能跟上你的节奏，同时提醒你收一收散落的事情。', '罗宾·威廉姆斯、马克·吐温式幽默作家、莫扎特');
INSERT INTO `mbti_types` VALUES ('ISTJ', '物流师', 'Logistician', '守护者', '#4298B4', '务实可靠、重事实的人，可靠是他们的代名词。', '你做事有章法，说到就能做到。你重视秩序、责任和承诺，不喜欢浮夸和临时变卦。你相信经过验证的方法，愿意用稳定的努力把事情做扎实。', '责任心强、说到做到；注重细节、条理清晰；稳定可靠、抗压性好；执行流程不打折扣', '不喜变化、灵活度低；对情绪表达不敏感；容易固执于旧方法；不擅长处理模糊和突发的混乱', '财务审计、法务合规、运维与质量、行政人事、供应链、工程技术、数据管理', '你的爱体现在稳定的行动和长期的承担上，不擅长甜言蜜语。提醒自己偶尔把在意说出口，对方才不会觉得被忽视。', '乔治·华盛顿、巴菲特式价值投资者、康德');
INSERT INTO `mbti_types` VALUES ('ISFJ', '守卫者', 'Defender', '守护者', '#4298B4', '专注而温暖的守护者，时刻准备保护所爱之人。', '你细心、耐心，习惯默默把照顾别人的事做好。你重视传统和承诺，喜欢可预期的生活。你不太争抢，但一旦认定的人和事，会守得很牢。', '体贴细致、责任感强；执行踏实、不夸口；善于照顾他人需求；忠诚、值得信赖', '不善于拒绝、容易过度承担；害怕冲突、习惯隐忍；对变化适应慢；容易忽略自己的需求', '医疗护理、教育、行政支持、人力资源、客户服务、财务出纳、社会工作', '你是那种让人安心的伴侣，用行动表达关心。要练习说出自己的委屈和期待，别让沉默累积成隔阂。', '特蕾莎修女式照护者、罗莎·帕克斯、《哈利·波特》中的纳威');
INSERT INTO `mbti_types` VALUES ('ESTJ', '总经理', 'Executive', '守护者', '#4298B4', '出色的管理者，在管理事务或人员方面无与伦比。', '你重视秩序和效率，喜欢把复杂的事情理成流程、分给人去做。你直接、果断，对规则和结果都有明确要求。你在混乱中会本能地站出来承担组织者的角色。', '组织和执行能力强；判断果断、立场清晰；重视承诺与秩序；善于把混乱变成流程', '过于强势、不够圆融；对情绪和不守规矩的人缺乏耐心；容易忽略创新的可能；说话太直', '运营管理、项目管理、生产制造、销售管理、行政总务、公共事务', '你在关系中有担当，也容易替对方做决定。多听听对方想要什么，比替他安排好一切更重要。', '亨利·福特、山姆·沃尔顿、曾国藩式实务派');
INSERT INTO `mbti_types` VALUES ('ESFJ', '执政官', 'Consul', '守护者', '#4298B4', '极有同情心、爱交际、乐于助人的人，总是热情地提供帮助。', '你在意人与人之间的和谐，擅长把大家照顾得妥帖。你重视关系和归属，愿意为集体付出。你对他人的情绪很敏感，也希望自己的付出被看见和认可。', '人际敏感度高；组织聚会和协调关系能力强；务实、乐于服务他人；忠诚、重视承诺', '过度在意他人评价；容易牺牲自己换和谐；对批评特别敏感；有时过于照顾表面和谐', '教育、医护、人力资源、客户关系、活动组织、销售服务、社区工作', '你热情、周到、愿意经营关系，是很好的伴侣。注意不要用付出换取认可，也别把关心变成催促。', '泰勒·斯威夫特式社交型艺人、戴安娜王妃（常被认为）');
INSERT INTO `mbti_types` VALUES ('ISTP', '鉴赏家', 'Virtuoso', '探险家', '#E4AE3A', '大胆而务实的实践者，擅长使用各种工具。', '你喜欢动手、喜欢弄清事物怎么运转。你冷静、独立，遇到问题先自己解决，不爱空谈。你对突发状况反应快，能在混乱中保持清醒的判断。', '动手和实操能力强；危机中冷静；逻辑清晰、不情绪化；学习新技能快', '不喜欢承诺和长期计划；表达情感少，容易显得冷淡；讨厌规则和束缚；容易临时起意', '工程技术、机械与自动化、运维、驾驶与操控、应急与救援、手工艺与设计', '你的爱很安静，体现在帮对方解决问题上。多说两句你的想法，别让沉默被误解成不在乎。', '克林特·伊斯特伍德、迈克尔·乔丹式运动员、飞行员与探险家');
INSERT INTO `mbti_types` VALUES ('ISFP', '探险家', 'Adventurer', '探险家', '#E4AE3A', '灵活、有魅力的艺术家，随时准备探索和体验新事物。', '你敏感、温和，重视当下的真实体验。你对美和氛围有天然的感知力，喜欢用行动而不是语言表达自己。你不喜欢冲突，也不喜欢被过多规则约束。', '审美与感知力强；温和、包容、不评判；灵活适应、活在当下；动手创作能力强', '回避冲突、容易委屈自己；缺乏长期规划；不擅长拒绝；对批评敏感', '设计、摄影与影像、手工艺、餐饮与美妆、护理、幼教、艺术表演', '你用陪伴和小惊喜表达感情，不喜欢被束缚。遇到问题请直接说出来，回避只会让误会变深。', '迈克尔·杰克逊、鲍勃·迪伦式艺术家、梵高（一般认为）');
INSERT INTO `mbti_types` VALUES ('ESTP', '企业家', 'Entrepreneur', '探险家', '#E4AE3A', '聪明、精力充沛、善于感知的人，真心享受边缘风险。', '你反应快、喜欢行动，讨厌空谈和冗长会议。你擅长在现实场景里抓机会、谈判、解决眼前问题。你享受刺激和竞争，也懂得审时度势。', '行动力和应变力强；社交灵活、善于谈判；现实、务实；抗压、敢于冒险', '缺乏耐心、容易冲动；不喜欢长期计划和理论；对他人感受不够细致；容易半途换方向', '销售与商务、创业、市场拓展、体育与竞技、应急管理、投资交易', '你带劲、直接、有趣，但也有点难管。多给对方确定的承诺和稳定的节奏，关系才不容易忽冷忽热。', '欧内斯特·海明威、麦当娜式艺人、企业家型创业者');
INSERT INTO `mbti_types` VALUES ('ESFP', '表演者', 'Entertainer', '探险家', '#E4AE3A', '自发、精力充沛、热情的人，生活在自己周围从不无聊。', '你是场上的开心果，擅长把气氛点燃。你关注当下、享受体验，对人有天然的亲和力。你不喜欢被计划和规则绑住，喜欢即兴和自由。', '热情、感染力强；人际亲和、容易交到朋友；感知力强、善于应变；行动力好', '缺乏长期规划和自律；容易分心、难以坚持；回避严肃冲突；对批评敏感', '表演与娱乐、销售、市场活动、旅游服务、餐饮、幼教、时尚与美妆', '你热烈、直接，把快乐带给身边的人。注意别用热闹掩盖问题，认真谈一次比一直逗笑更有用。', '玛丽莲·梦露、杰米·福克斯式艺人、阿黛尔（常被认为）');
